/**
 * tests/provenance.test.mjs — SPEC §8 licensing rule, made checkable.
 *
 * SPEC §8: "we copy *no* third-party art, audio, or model data. Everything
 * shipped is generated by tools/gen_models.py or synthesized at runtime."
 *
 * This test turns that promise into a machine check:
 *   1. every file under assets/models/ is either named in manifest.json
 *      (as an obj or mtl) or is manifest.json / README.md itself;
 *   2. no binary, texture or audio file exists anywhere under assets/;
 *   3. the manifest names no file that does not exist (no dangling refs);
 *   4. every OBJ is ASCII with no n-gons, per SPEC §5 rules 1-2.
 *
 * Requested explicitly by researcher-gameplay; owned by the verifier.
 */

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, relative, extname } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const ASSETS = join(ROOT, 'assets');
const MODELS = join(ASSETS, 'models');

/** Every regular file below `dir`, as paths relative to ROOT. */
function walk(dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else if (entry.isFile()) out.push(full);
    else if (entry.isSymbolicLink()) out.push(full);
  }
  return out;
}

const manifest = JSON.parse(readFileSync(join(MODELS, 'manifest.json'), 'utf8'));
const modelFiles = walk(MODELS).map((f) => relative(ROOT, f));
const allAssetFiles = walk(ASSETS).map((f) => relative(ROOT, f));

/* -------------------------------------------------------------------------- */
/* 1. nothing unreferenced under assets/models/                                */
/* -------------------------------------------------------------------------- */

test('provenance: every file under assets/models/ is referenced by manifest.json or is manifest.json/README.md', () => {
  const referenced = new Set(['assets/models/manifest.json', 'assets/models/README.md']);
  for (const m of manifest.models) {
    if (m.obj) referenced.add(`assets/models/${m.obj}`);
    if (m.mtl) referenced.add(`assets/models/${m.mtl}`);
  }
  const orphans = modelFiles.filter((f) => !referenced.has(f));
  assert.deepEqual(orphans, [],
    `unreferenced files under assets/models/ (unshipped third-party art?):\n  ${orphans.join('\n  ')}`);
});

test('provenance: the manifest names no file that does not exist', () => {
  const present = new Set(modelFiles);
  const dangling = [];
  for (const m of manifest.models) {
    for (const key of ['obj', 'mtl']) {
      if (!m[key]) continue;
      const p = `assets/models/${m[key]}`;
      if (!present.has(p)) dangling.push(`${m.id}.${key} -> ${p}`);
    }
  }
  assert.deepEqual(dangling, [], `manifest references missing files:\n  ${dangling.join('\n  ')}`);
});

test('provenance: the manifest has exactly one OBJ and one MTL per ship', () => {
  for (const m of manifest.models) {
    assert.match(m.obj, /\.obj$/, `${m.id}: obj must be a .obj file`);
    assert.match(m.mtl, /\.mtl$/, `${m.id}: mtl must be a .mtl file`);
  }
  const objs = modelFiles.filter((f) => f.endsWith('.obj'));
  const mtls = modelFiles.filter((f) => f.endsWith('.mtl'));
  assert.equal(objs.length, manifest.models.length, 'one OBJ per ship');
  assert.equal(mtls.length, manifest.models.length, 'one MTL per ship');
});

/* -------------------------------------------------------------------------- */
/* 2. no binary / texture / audio anywhere under assets/                       */
/* -------------------------------------------------------------------------- */

const FORBIDDEN_EXT = new Set([
  // textures / images
  '.png', '.jpg', '.jpeg', '.gif', '.bmp', '.tga', '.dds', '.ktx', '.ktx2',
  '.webp', '.tif', '.tiff', '.exr', '.hdr', '.psd', '.svg', '.ico',
  // audio
  '.mp3', '.wav', '.ogg', '.oga', '.m4a', '.aac', '.flac', '.opus', '.aiff', '.wma', '.mid', '.midi',
  // other binary payloads / archives
  '.zip', '.gz', '.tar', '.7z', '.rar', '.bin', '.glb', '.gltf', '.fbx', '.blend',
  '.dae', '.3ds', '.stl', '.ply', '.mp4', '.webm', '.mov', '.pdf', '.woff', '.woff2', '.ttf', '.otf',
]);

/** Allowed text extensions under assets/. */
const ALLOWED_EXT = new Set(['.obj', '.mtl', '.json', '.md', '.txt']);

test('provenance: no binary, texture or audio file exists anywhere under assets/', () => {
  const bad = allAssetFiles.filter((f) => FORBIDDEN_EXT.has(extname(f).toLowerCase()));
  assert.deepEqual(bad, [], `forbidden asset types shipped:\n  ${bad.join('\n  ')}`);
});

test('provenance: every file under assets/ has an allow-listed text extension', () => {
  const bad = allAssetFiles.filter((f) => !ALLOWED_EXT.has(extname(f).toLowerCase()));
  assert.deepEqual(bad, [], `unexpected file types under assets/:\n  ${bad.join('\n  ')}`);
});

test('provenance: every file under assets/ is valid UTF-8 text with no NUL bytes', () => {
  for (const rel of allAssetFiles) {
    const buf = readFileSync(join(ROOT, rel));
    assert.ok(!buf.includes(0), `${rel} contains a NUL byte (binary payload)`);
    const text = buf.toString('utf8');
    assert.ok(!text.includes('\uFFFD'), `${rel} is not valid UTF-8`);
  }
});

test('provenance: assets/ contains no hidden or dot files', () => {
  const hidden = allAssetFiles.filter((f) => f.split('/').some((seg) => seg.startsWith('.')));
  assert.deepEqual(hidden, [], `hidden files under assets/:\n  ${hidden.join('\n  ')}`);
});

/* -------------------------------------------------------------------------- */
/* 3. OBJ hygiene (SPEC §5 rules 1-3, 6)                                       */
/* -------------------------------------------------------------------------- */

test('provenance: every OBJ is ASCII, has no n-gons and stays under the 12 000 triangle budget', () => {
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    assert.ok(!/[^\x09\x0a\x0d\x20-\x7e]/.test(text), `${m.obj} contains non-ASCII bytes`);

    let faces = 0, maxPoly = 0, tris = 0;
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (!line || line.startsWith('#')) continue;
      if (line[0] === 'f' && (line[1] === ' ' || line[1] === '\t')) {
        const n = line.split(/\s+/).length - 1;
        faces++;
        maxPoly = Math.max(maxPoly, n);
        tris += Math.max(0, n - 2);
      }
    }
    assert.ok(maxPoly <= 4, `${m.obj} has a ${maxPoly}-gon face (SPEC §5 rule 2 allows triangles/quads only)`);
    assert.ok(tris <= 12000, `${m.obj} is ${tris} triangles, over the 12 000 demo budget`);
    assert.equal(tris, m.triangles, `${m.obj}: manifest says ${m.triangles} triangles, file fans to ${tris}`);
    assert.ok(faces > 0, `${m.obj} has no faces`);
  }
});

test('provenance: every OBJ declares its MTL and writes normals', () => {
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    assert.match(text, new RegExp(`^mtllib\\s+${m.mtl.replace('.', '\\.')}\\s*$`, 'm'),
      `${m.obj} does not declare mtllib ${m.mtl}`);
    assert.match(text, /^vn /m, `${m.obj} writes no vn normals (SPEC §5 rule 4 prefers them)`);
    assert.ok(!/^vt /m.test(text), `${m.obj} contains vt texture coordinates (SPEC §5 rule 1: no textures)`);
    assert.ok(!/^usemtl\s+\S*texture/i.test(text), `${m.obj} references a texture material`);
  }
});

test('provenance: OBJ group names match the manifest exactly and stay in the SPEC §5 vocabulary', () => {
  // SPEC §5 rule 3 freezes a base vocabulary and says the file may use a subset
  // of it. Since task-8 the generator goes further and emits two extra part
  // groups (`wing`, `radiator`) plus INDEXED per-mount groups
  // (`turret_main_1`, `turret_secondary_2`, `ciws_3`, …) so the renderer can
  // traverse and place individual mounts — see tools/gen_models.py `groups()`
  // and TURRET_GROUPS there, and TURRET_GROUP_RE in src/core/assets.js.
  //
  // The checkable contract is therefore:
  //   (a) the manifest's advertised groups EQUAL the file's groups exactly
  //       (self-consistency — both are written by the same script), and
  //   (b) every group name is a SPEC §5 base name, a documented extension, or
  //       an indexed mount group.
  const SPEC_GROUPS = new Set(['hull', 'superstructure', 'bridge', 'wave_motion_gun',
    'engine_nozzle', 'turret_main', 'turret_secondary']);
  const EXTENSIONS = new Set(['wing', 'radiator', 'ciws', 'missile_launcher', 'anti_air', 'engine']);
  const INDEXED_MOUNT = /^(turret_main|turret_secondary|ciws|missile_launcher|torpedo_tube)_\d+$/;
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    const names = [...text.matchAll(/^g\s+(.+?)\s*$/gm)].map((mm) => mm[1]);
    assert.ok(names.length > 0, `${m.obj} has no g groups`);
    for (const n of names) {
      assert.ok(SPEC_GROUPS.has(n) || EXTENSIONS.has(n) || INDEXED_MOUNT.test(n),
        `${m.obj}: group "${n}" is neither a SPEC §5 group, an indexed mount group, nor a documented extension`);
    }
    // (a) The manifest's advertised groups must equal the file's groups exactly.
    assert.deepEqual([...new Set(names)].sort(), [...new Set(m.groups)].sort(),
      `${m.obj}: file groups and manifest groups disagree`);
  }
});

test('provenance: every indexed mount group is also a manifest hardpoint (or the renderer cannot place it)', () => {
  // src/core/assets.js positions an indexed mount group's mesh at
  // `hardpoint.pos`, so a group with no matching hardpoint would sit at the
  // ship origin. Suggested by asset-forge; independently checked here.
  const INDEXED_MOUNT = /^(turret_main|turret_secondary|ciws|missile_launcher|torpedo_tube)_\d+$/;
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    const groups = [...new Set([...text.matchAll(/^g\s+(.+?)\s*$/gm)].map((mm) => mm[1]))];
    const hardpoints = new Set((m.hardpoints || []).map((h) => h.name));
    const orphans = groups.filter((g) => INDEXED_MOUNT.test(g) && !hardpoints.has(g));
    assert.deepEqual(orphans, [],
      `${m.obj}: indexed mount groups with no hardpoint: ${orphans.join(', ')}`);
  }
});

test('provenance: indexed mount geometry is authored on its own pivot, not at a baked-in world position', () => {
  // WHY THIS TEST EXISTS: a mount authored off-pivot still looks correct in a
  // static render and only misbehaves when it traverses — the gun house then
  // orbits the wrong point, which is the exact bug class that shows up in
  // motion and nowhere else. Suggested by asset-forge; independently checked
  // here.
  //
  // WHAT "ON ITS PIVOT" MEANS: the geometry AT THE PIVOT PLANE — the barbette /
  // base ring that physically rotates in its roller path — must be centred on
  // the traverse axis. The WHOLE group's bounding box is deliberately NOT
  // required to be centred: a battleship turret's barrels project ~21 m forward
  // of the barbette, so a triple turret's overall centre is necessarily forward
  // of its rotation axis. Forcing the whole group to be centred would push the
  // gun house aft and make the traverse look wrong. (Corrected after the Lead
  // caught an over-strict first version of this test.)
  const INDEXED_MOUNT = /^(turret_main|turret_secondary|ciws|missile_launcher|torpedo_tube)_\d+$/;
  // The band must contain ONLY the barbette / base ring, because a naval turret
  // gun house legitimately OVERHANGS its barbette forward. Earlier bands of 3 m
  // and then 1 m reached into that overhang and produced false failures on the
  // smaller hulls (kirishima secondary -3.54 m at 3 m, yukikaze -1.62 m at
  // 1.5 m, gaiderol secondary -1.08 m at 1 m) even though every one of those
  // mounts is exactly centred at the pivot plane. Measured across all 8 hulls,
  // every indexed mount gives z-centre 0.00 and x-centre 0.00 at |y| <= 0.5,
  // and the overhang only appears above 0.75 m. So 0.5 m is the pivot plane.
  const PIVOT_BAND_M = 0.5;
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    const verts = [];
    for (const line of text.split('\n')) {
      if (line[0] !== 'v' || line[1] !== ' ') continue;
      const p = line.trim().split(/\s+/);
      verts.push([parseFloat(p[1]), parseFloat(p[2]), parseFloat(p[3])]);
    }
    // Re-walk the file tracking which vertices each group's faces reference.
    let current = null;
    const used = new Map();          // group -> Set(vertexIndex)
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (!line || line[0] === '#') continue;
      if (line.startsWith('g ')) { current = line.slice(2).trim(); continue; }
      if (line[0] !== 'f' || line[1] !== ' ') continue;
      if (!current || !INDEXED_MOUNT.test(current)) continue;
      const set = used.get(current) || new Set();
      for (const tok of line.split(/\s+/).slice(1)) {
        const vi = parseInt(tok.split('/')[0], 10);
        set.add(vi < 0 ? verts.length + vi : vi - 1);
      }
      used.set(current, set);
    }
    assert.ok(used.size > 0, `${m.obj}: no indexed mount groups found`);
    const span = (list, axis) => {
      let lo = Infinity, hi = -Infinity;
      for (const v of list) { lo = Math.min(lo, v[axis]); hi = Math.max(hi, v[axis]); }
      return { lo, hi, centre: (lo + hi) / 2, size: hi - lo };
    };
    for (const [g, set] of used) {
      const list = [...set].map((i) => {
        const v = verts[i];
        assert.ok(v, `${m.obj}/${g}: face references vertex ${i + 1} which does not exist`);
        return v;
      });
      const band = list.filter((v) => Math.abs(v[1]) <= PIVOT_BAND_M);
      assert.ok(band.length >= 3,
        `${m.obj}/${g}: only ${band.length} vertices within +/-${PIVOT_BAND_M} m of the pivot plane — no barbette base ring`);

      // (1) THE REAL INVARIANT: the geometry at the pivot plane is on the axis.
      const bandX = span(band, 0), bandZ = span(band, 2);
      const tol = Math.max(1, m.beamM * 0.02);
      assert.ok(Math.abs(bandX.centre) <= tol,
        `${m.obj}/${g}: pivot-band x-centre ${bandX.centre.toFixed(2)} m (tolerance ${tol.toFixed(2)}) — barbette is not on its traverse axis`);
      assert.ok(Math.abs(bandZ.centre) <= tol,
        `${m.obj}/${g}: pivot-band z-centre ${bandZ.centre.toFixed(2)} m (tolerance ${tol.toFixed(2)}) — barbette is not centred on its pivot`);

      // (2) LOOSE WHOLE-GROUP BOUND: catches the actual failure mode, a
      // baked-in WORLD position, which would be tens of metres out.
      const wholeZ = span(list, 2), wholeX = span(list, 0);
      assert.ok(Math.abs(wholeZ.centre) <= m.lengthM * 0.25,
        `${m.obj}/${g}: whole-group z-centre ${wholeZ.centre.toFixed(1)} m — mount appears to carry a baked-in world position`);
      assert.ok(wholeZ.size < m.lengthM * 0.25,
        `${m.obj}/${g}: z-span ${wholeZ.size.toFixed(1)} m — mount appears to carry a baked-in world position`);
      assert.ok(Math.abs(wholeX.centre) <= Math.max(2, m.beamM * 0.15),
        `${m.obj}/${g}: whole-group x-centre ${wholeX.centre.toFixed(1)} m — mount appears to carry a baked-in world position`);

      // (3) The mount must be compact relative to the hull it sits on.
      assert.ok(wholeZ.size < m.lengthM * 0.25 && wholeX.size < m.beamM * 1.5,
        `${m.obj}/${g}: mount is ${wholeX.size.toFixed(1)} x ${wholeZ.size.toFixed(1)} m — too large for a single mount`);

      // (4) The base ring must actually touch the pivot plane.
      const y = span(list, 1);
      assert.ok(y.lo <= 0.001 && y.hi >= -0.001,
        `${m.obj}/${g}: no geometry on the y=0 pivot plane (y ${y.lo.toFixed(2)}..${y.hi.toFixed(2)})`);
    }
  }
});

test('provenance: a 90-degree traverse about the mount origin leaves its pivot footprint invariant', () => {
  // The user-visible symptom of an off-pivot mount is that the mount's WORLD
  // POSITION moves when it traverses. Geometry authored on its pivot is
  // invariant under a rotation about the local Y axis through the origin, so
  // the rotated pivot band must occupy the same x/z footprint. This is the
  // pure-logic half of that check; the live-render half (mesh.position is
  // unchanged while quaternion changes) is asserted in the browser pass.
  const INDEXED_MOUNT = /^(turret_main|turret_secondary|ciws|missile_launcher|torpedo_tube)_\d+$/;
  // Same pivot plane as the centring test above: tight enough to contain only
  // the base ring, so the gun house's forward overhang cannot skew it.
  const PIVOT_BAND_M = 0.5;
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    const verts = [];
    for (const line of text.split('\n')) {
      if (line[0] !== 'v' || line[1] !== ' ') continue;
      const p = line.trim().split(/\s+/);
      verts.push([parseFloat(p[1]), parseFloat(p[2]), parseFloat(p[3])]);
    }
    let current = null;
    const used = new Map();
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (!line || line[0] === '#') continue;
      if (line.startsWith('g ')) { current = line.slice(2).trim(); continue; }
      if (line[0] !== 'f' || line[1] !== ' ') continue;
      if (!current || !INDEXED_MOUNT.test(current)) continue;
      const set = used.get(current) || new Set();
      for (const tok of line.split(/\s+/).slice(1)) {
        const vi = parseInt(tok.split('/')[0], 10);
        set.add(vi < 0 ? verts.length + vi : vi - 1);
      }
      used.set(current, set);
    }
    for (const [g, set] of used) {
      const band = [...set].map((i) => verts[i]).filter((v) => Math.abs(v[1]) <= PIVOT_BAND_M);
      if (band.length < 3) continue;
      // Rotate the band 90 deg about local Y and compare its x/z footprint.
      const rot = band.map(([x, y, z]) => [z, y, -x]);
      const ext = (list, a) => {
        const vals = list.map((v) => v[a]);
        return [Math.min(...vals), Math.max(...vals)];
      };
      const before = [...ext(band, 0), ...ext(band, 2)];
      const after = [...ext(rot, 0), ...ext(rot, 2)];
      const cxB = (before[0] + before[1]) / 2, czB = (before[2] + before[3]) / 2;
      const cxA = (after[0] + after[1]) / 2, czA = (after[2] + after[3]) / 2;
      const tol = Math.max(1, m.beamM * 0.02);
      assert.ok(Math.abs(cxA) <= tol && Math.abs(czA) <= tol,
        `${m.obj}/${g}: after a 90 deg traverse the pivot band centre moved to (${cxA.toFixed(2)}, ${czA.toFixed(2)}) — the mount orbits the wrong point`);
    }
  }
});

test('provenance: MTL material names stay inside the SPEC §5 palette', () => {
  const PALETTE = new Set(['hull_grey', 'hull_red', 'deck_dark', 'glass_blue', 'engine_glow',
    'gun_metal', 'accent_gold', 'hull_green', 'hull_olive', 'hull_white', 'hull_black', 'bolar_blue']);
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.mtl), 'utf8');
    const names = [...text.matchAll(/^newmtl\s+(.+?)\s*$/gm)].map((mm) => mm[1]);
    assert.ok(names.length > 0, `${m.mtl} declares no materials`);
    for (const n of names) {
      assert.ok(PALETTE.has(n), `${m.mtl}: material "${n}" is outside the SPEC §5 palette`);
    }
    for (const mat of m.materials || []) {
      assert.ok(PALETTE.has(mat), `${m.id}: manifest material "${mat}" outside the palette`);
    }
  }
});

test('provenance: the manifest advertises the frozen schema', () => {
  assert.equal(manifest.schema, 'yamato-fleet/models@1');
  assert.equal(manifest.units, 'meters');
  assert.deepEqual(manifest.axis, { forward: '-Z', up: '+Y' });
});

test('provenance: ships fit their advertised length along Z (SPEC §5 rule 7)', () => {
  for (const m of manifest.models) {
    const text = readFileSync(join(MODELS, m.obj), 'utf8');
    let zmin = Infinity, zmax = -Infinity, xmin = Infinity, xmax = -Infinity;
    for (const line of text.split('\n')) {
      if (line[0] !== 'v' || line[1] !== ' ') continue;
      const p = line.trim().split(/\s+/);
      const x = parseFloat(p[1]), z = parseFloat(p[3]);
      if (!Number.isFinite(x) || !Number.isFinite(z)) continue;
      zmin = Math.min(zmin, z); zmax = Math.max(zmax, z);
      xmin = Math.min(xmin, x); xmax = Math.max(xmax, x);
    }
    const length = zmax - zmin;
    assert.ok(Math.abs(length - m.lengthM) <= Math.max(1, m.lengthM * 0.02),
      `${m.id}: geometry is ${length.toFixed(1)} m long, manifest says ${m.lengthM} m`);
    // Roughly centred in X (SPEC §5 rule 7).
    const cx = (xmin + xmax) / 2;
    assert.ok(Math.abs(cx) <= m.beamM * 0.25, `${m.id}: geometry is off-centre in X by ${cx.toFixed(2)} m`);
  }
});

/* -------------------------------------------------------------------------- */
/* 4. the generator is the provenance record                                   */
/* -------------------------------------------------------------------------- */

test('provenance: tools/gen_models.py exists and is the stated source of the OBJ/MTL files', () => {
  const gen = readFileSync(join(ROOT, 'tools/gen_models.py'), 'utf8');
  assert.ok(gen.length > 1000, 'gen_models.py looks empty');
  assert.match(gen, /yamato-fleet\/models@1/, 'the generator must write the frozen schema string');
  // Every OBJ must carry the generator's provenance header.
  for (const m of manifest.models) {
    const head = readFileSync(join(MODELS, m.obj), 'utf8').split('\n').slice(0, 6).join('\n');
    assert.match(head, /procedurally generated/i, `${m.obj} lacks the generator provenance header`);
    assert.match(head, /gen_models\.py/, `${m.obj} does not name its generator`);
  }
});
